#!/usr/bin/env python3
"""dsq - a command-line SQL tool for data files.

Reimplemented from observed behavior of the original Go tool.
"""
import sys
import os
import io
import json
import csv
import sqlite3
import re
import tempfile
import hashlib
import zipfile
import xml.etree.ElementTree as ET
from collections import OrderedDict


HELP_TEXT = """dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \\
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq
"""


# Mimetype map – extension (lowercase) -> canonical format name
EXT_MIME = {
    'csv': 'csv',
    'tsv': 'tsv',
    'json': 'json',
    'ndjson': 'ndjson',
    'jsonl': 'jsonl',
    'xlsx': 'xlsx',
    'parquet': 'parquet',
    'ods': 'ods',
    'avro': 'avro',
    'orc': 'orc',
    'logfmt': 'logfmt',
}


def eprint(*args):
    print(*args, file=sys.stderr)


def detect_format_by_ext(path):
    base = os.path.basename(path)
    if '.' not in base:
        return None
    ext = base.rsplit('.', 1)[1]
    # Case sensitive - only lowercase extensions work
    return EXT_MIME.get(ext)


def read_csv_text(text, delim=','):
    rdr = csv.DictReader(io.StringIO(text), delimiter=delim)
    out = []
    for row in rdr:
        # DictReader returns OrderedDict; keep
        out.append(dict(row))
    return out, ('csv' if delim == ',' else 'tsv')


def read_json_text(text, path_for_error):
    """Parse as JSON array-of-objects, JSON object, or NDJSON stream."""
    text = text.strip()
    if not text:
        raise ValueError("EOF")
    try:
        obj = json.loads(text)
        return obj
    except json.JSONDecodeError:
        # Try NDJSON – try each line
        out = []
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                out.append(json.loads(line))
            except json.JSONDecodeError as e:
                raise ValueError("invalid character '%s' looking for beginning of value" % line[0]) from e
        return out


def read_ndjson_text(text):
    out = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        out.append(json.loads(line))
    return out


def read_logfmt_text(text):
    """Parse logfmt - key=value space-separated."""
    out = []
    for line in text.splitlines():
        line = line.rstrip()
        if not line:
            continue
        rec = OrderedDict()
        i = 0
        n = len(line)
        while i < n:
            while i < n and line[i] == ' ':
                i += 1
            if i >= n:
                break
            # Read key
            j = i
            while j < n and line[j] not in ' =':
                j += 1
            key = line[i:j]
            i = j
            if i < n and line[i] == '=':
                i += 1
                if i < n and line[i] == '"':
                    # quoted value
                    i += 1
                    val_chars = []
                    while i < n and line[i] != '"':
                        if line[i] == '\\' and i + 1 < n:
                            val_chars.append(line[i + 1])
                            i += 2
                        else:
                            val_chars.append(line[i])
                            i += 1
                    if i < n:
                        i += 1  # skip closing quote
                    value = ''.join(val_chars)
                else:
                    j = i
                    while j < n and line[j] != ' ':
                        j += 1
                    value = line[i:j]
                    i = j
            else:
                value = ""
            rec[key] = value
        out.append(rec)
    return out


# ---- XLSX reading (minimal) ----

def col_letter_to_idx(letters):
    n = 0
    for c in letters:
        n = n * 26 + (ord(c) - ord('A') + 1)
    return n - 1


def parse_xlsx_file(path):
    """Parse an xlsx file into {sheetName: [dict...]} mapping."""
    with zipfile.ZipFile(path, 'r') as z:
        # Read shared strings
        shared = []
        if 'xl/sharedStrings.xml' in z.namelist():
            with z.open('xl/sharedStrings.xml') as f:
                tree = ET.parse(f)
                root = tree.getroot()
                ns = {'a': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                for si in root.findall('a:si', ns):
                    # Accumulate text across all <t> children (handles rich text)
                    parts = []
                    for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'):
                        parts.append(t.text or '')
                    shared.append(''.join(parts))

        # Read workbook to get sheet names and rIds
        sheet_info = []  # list of (name, rid)
        with z.open('xl/workbook.xml') as f:
            tree = ET.parse(f)
            root = tree.getroot()
            ns = {'a': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
                  'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
            for sh in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet'):
                name = sh.get('name')
                rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
                sheet_info.append((name, rid))

        # Read relationships to map rid -> path
        rels = {}
        with z.open('xl/_rels/workbook.xml.rels') as f:
            tree = ET.parse(f)
            root = tree.getroot()
            for rel in root.iter():
                if rel.tag.endswith('Relationship'):
                    rels[rel.get('Id')] = rel.get('Target')

        result = OrderedDict()
        for name, rid in sheet_info:
            target = rels.get(rid, '')
            if target.startswith('/'):
                target = target[1:]
            else:
                target = 'xl/' + target
            if target not in z.namelist():
                continue
            with z.open(target) as f:
                rows = parse_xlsx_sheet(f, shared)
            result[name] = rows
        return result


def parse_xlsx_sheet(stream, shared_strings):
    """Parse a sheet XML stream into list-of-dicts."""
    ns_main = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
    rows = []
    header = None
    for event, elem in ET.iterparse(stream, events=('end',)):
        if elem.tag == '{%s}row' % ns_main:
            row_cells = {}
            max_col = -1
            for c in elem.findall('{%s}c' % ns_main):
                ref = c.get('r', '')
                # extract letters
                letters = ''
                for ch in ref:
                    if ch.isalpha():
                        letters += ch
                    else:
                        break
                if not letters:
                    continue
                col_idx = col_letter_to_idx(letters)
                max_col = max(max_col, col_idx)
                t = c.get('t')
                v = c.find('{%s}v' % ns_main)
                inline = c.find('{%s}is' % ns_main)
                if t == 's':
                    if v is not None and v.text is not None:
                        try:
                            idx = int(v.text)
                            value = shared_strings[idx]
                        except (ValueError, IndexError):
                            value = ''
                    else:
                        value = ''
                elif t == 'inlineStr' and inline is not None:
                    value = ''
                    for tn in inline.iter('{%s}t' % ns_main):
                        value += tn.text or ''
                elif t == 'b':
                    value = 'TRUE' if (v is not None and v.text == '1') else 'FALSE'
                elif v is not None and v.text is not None:
                    value = v.text
                else:
                    value = ''
                row_cells[col_idx] = value
            if header is None:
                header = []
                for i in range(max_col + 1):
                    header.append(row_cells.get(i, ''))
            else:
                rec = OrderedDict()
                for i, h in enumerate(header):
                    rec[h] = row_cells.get(i, '')
                rows.append(rec)
            elem.clear()
    return rows


# ---- Schema inference ----

def infer_schema(value):
    """Infer schema for a JSON-like value according to dsq's schema model."""
    if value is None:
        return {"kind": "unknown"}
    if isinstance(value, bool):
        return {"kind": "scalar", "scalar": "boolean"}
    if isinstance(value, (int, float)):
        return {"kind": "scalar", "scalar": "number"}
    if isinstance(value, str):
        return {"kind": "scalar", "scalar": "string"}
    if isinstance(value, list):
        if not value:
            return {"kind": "array", "array": {"kind": "unknown"}}
        # Merge schemas of all elements
        elem_schemas = [infer_schema(x) for x in value]
        merged = merge_schemas(elem_schemas)
        return {"kind": "array", "array": merged}
    if isinstance(value, dict):
        # Object: collect schema for each key.  Keys that appear in one record
        # but not another end up with a 'null' alternative.
        obj_schema = OrderedDict()
        for k, v in value.items():
            obj_schema[k] = infer_schema(v)
        return {"kind": "object", "object": obj_schema}
    return {"kind": "unknown"}


def merge_schemas(schemas):
    """Merge a list of schemas into one (may be 'varied')."""
    if not schemas:
        return {"kind": "unknown"}
    # Deduplicate by canonical form (sort keys)
    unique = []
    seen = []
    for s in schemas:
        key = canonical_schema(s)
        if key not in seen:
            seen.append(key)
            unique.append(s)
    # Merge object schemas by unioning keys
    obj_schemas = [s for s in unique if s.get("kind") == "object"]
    non_obj = [s for s in unique if s.get("kind") != "object"]
    if obj_schemas:
        merged_obj = OrderedDict()
        for s in obj_schemas:
            for k, v in s.get("object", {}).items():
                if k in merged_obj:
                    merged_obj[k] = merge_schemas([merged_obj[k], v])
                else:
                    merged_obj[k] = v
        # Any records missing this key get "null" merged in
        # Count how many records had each key
        key_counts = OrderedDict()
        for s in obj_schemas:
            for k in s.get("object", {}):
                key_counts[k] = key_counts.get(k, 0) + 1
        total = len(obj_schemas)
        for k, count in key_counts.items():
            if count < total:
                merged_obj[k] = merge_schemas([merged_obj[k], {"kind": "scalar", "scalar": "null"}])
        obj_result = {"kind": "object", "object": merged_obj}
        if not non_obj:
            return obj_result
        unique = non_obj + [obj_result]
    if len(unique) == 1:
        return unique[0]
    return {"kind": "varied", "varied": unique}


def canonical_schema(s):
    try:
        return json.dumps(s, sort_keys=True)
    except TypeError:
        return str(s)


def format_schema_pretty(schema, indent=0):
    """Pretty print a schema tree."""
    pad = '  ' * indent
    k = schema.get("kind", "unknown")
    if k == "scalar":
        return pad + schema.get("scalar", "") + "\n"
    if k == "unknown":
        return pad + "unknown\n"
    if k == "array":
        out = pad + "Array of\n"
        out += format_schema_pretty(schema.get("array", {}), indent + 1)
        return out
    if k == "object":
        out = pad + "Object of\n"
        for key, val in schema.get("object", {}).items():
            out += pad + "  " + key + " of\n"
            out += format_schema_pretty(val, indent + 2)
        return out
    if k == "varied":
        out = pad + "Varied of\n"
        for v in schema.get("varied", []):
            out += format_schema_pretty(v, indent + 1)
        return out
    return pad + str(k) + "\n"


def format_schema_json(schema):
    return json.dumps(schema, indent=2)


# ---- SQL execution ----

def flatten_record(rec):
    """Flatten a dict with nested objects into flat key=val with dot keys,
    serialize arrays/unknowns to JSON strings."""
    out = OrderedDict()
    def _rec(prefix, value):
        if isinstance(value, dict):
            for k, v in value.items():
                nk = (prefix + '.' + k) if prefix else k
                _rec(nk, v)
        elif isinstance(value, list):
            out[prefix] = json.dumps(value, separators=(',', ':'))
        else:
            out[prefix] = value
    for k, v in rec.items():
        _rec(k, v)
    return out


def build_table_for_records(conn, table_name, records):
    """Create a table from list of dicts. Columns = union of all keys."""
    flat_records = [flatten_record(r) if isinstance(r, dict) else {'_': r} for r in records]
    # Union of keys in order of first appearance
    cols = []
    seen = set()
    for r in flat_records:
        for k in r.keys():
            if k not in seen:
                seen.add(k)
                cols.append(k)
    # Create table
    escaped_cols = [('"' + c.replace('"', '""') + '"') for c in cols]
    stmt = 'CREATE TABLE "%s" (%s)' % (table_name.replace('"', '""'), ', '.join(escaped_cols))
    conn.execute(stmt)
    if flat_records:
        placeholders = ','.join(['?'] * len(cols))
        insert = 'INSERT INTO "%s" VALUES (%s)' % (table_name.replace('"', '""'), placeholders)
        rows_to_insert = []
        for r in flat_records:
            rows_to_insert.append([coerce_sql_value(r.get(c)) for c in cols])
        conn.executemany(insert, rows_to_insert)
    return cols


def coerce_sql_value(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return 1 if v else 0
    if isinstance(v, (int, float, str)):
        return v
    return json.dumps(v, separators=(',', ':'))


def replace_table_refs(query, n_tables):
    """Replace {N} with t_N, {} with t_0."""
    # Replace {} first with t_0
    query = query.replace('{}', 't_0')
    # Replace {N}
    query = re.sub(r'\{(\d+)\}', r't_\1', query)
    return query


def run_query(records_per_file, query):
    """Run SQL against records.  Returns (columns, rows-as-list-of-dicts)."""
    conn = sqlite3.connect(':memory:')
    conn.row_factory = sqlite3.Row
    for i, records in enumerate(records_per_file):
        build_table_for_records(conn, 't_%d' % i, records)
    conn.commit()
    final_query = replace_table_refs(query, len(records_per_file))
    cur = conn.execute(final_query)
    columns = [d[0] for d in cur.description] if cur.description else []
    rows = []
    for r in cur.fetchall():
        row = OrderedDict()
        for c in columns:
            row[c] = r[c]
        rows.append(row)
    conn.close()
    return columns, rows


# ---- Output ----

def format_json_array(rows):
    """Format a list of dict rows as a dsq-style JSON output."""
    if not rows:
        return "[]\n"
    # Each row is a dict, each rendered per-line, joined by ',\n'
    parts = []
    for r in rows:
        parts.append(json.dumps(r, separators=(',', ':'), ensure_ascii=False))
    return '[' + ',\n'.join(parts) + ']\n'


def format_value_for_pretty(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        # Use go-like %g with -1 precision
        return go_format_float(v)
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return v
    return json.dumps(v, separators=(',', ':'))


def go_format_float(f):
    """Approximate Go's strconv.FormatFloat(f, 'g', -1, 64)."""
    if f != f:  # NaN
        return "NaN"
    if f == float('inf'):
        return "+Inf"
    if f == float('-inf'):
        return "-Inf"
    if f == 0.0:
        return "0"
    absf = abs(f)
    # Go uses exponent form for |f| < 1e-4 or >= 1e21 but for %g -1 with 64-bit
    # it switches between formats based on exponent; roughly:
    # use decimal if -4 <= exp < precision (adjusted).
    # Empirical from observation:
    #  1.0 -> "1", 1.5 -> "1.5"
    #  1000000 -> "1e+06"
    #  999999 -> "999999"
    #  1234567890 -> "1.23456789e+09"
    # So it's essentially Python's repr which is close to Go's %g.
    # Python's float repr is designed to round-trip.
    s = repr(f)
    # If it's like "1.0" and integral, Go would print "1".
    if s.endswith('.0'):
        try:
            if float(s).is_integer():
                # Check magnitude - need scientific for very large
                iv = int(f)
                if abs(iv) >= 1_000_000:
                    return go_sci(f)
                return str(iv)
        except (ValueError, OverflowError):
            pass
    if 'e' in s:
        # Normalize Python's 'e+06' vs 'e+6'
        s = re.sub(r'e([+-])0*(\d)', lambda m: 'e' + m.group(1) + (m.group(2) if len(m.group(2)) > 1 else '0' + m.group(2)), s)
        # Go uses at least 2-digit exponent
        s = re.sub(r'e([+-])(\d)$', r'e\g<1>0\2', s)
        return s
    # Switch to scientific if magnitude >= 1e21 (Go does) - but also for integer-valued large nums
    if absf >= 1e21:
        return go_sci(f)
    return s


def go_sci(f):
    # Format as Go: e.g., "1e+06" or "1.23456789e+09"
    s = "%.15e" % f
    # Parse out mantissa and exponent
    m = re.match(r'(-?\d+)\.(\d+)e([+-]\d+)', s)
    if not m:
        return s
    sign_exp = m.group(3)
    mantissa = m.group(1)
    frac = m.group(2).rstrip('0')
    # normalize exponent to two digits at least
    exp_n = int(sign_exp)
    sign = '+' if exp_n >= 0 else '-'
    exp_s = sign + ('%02d' % abs(exp_n))
    if frac:
        return mantissa + '.' + frac + 'e' + exp_s
    return mantissa + 'e' + exp_s


def visual_width(s):
    """Crude visual width – count characters (assumes ASCII-ish)."""
    try:
        return len(s)
    except TypeError:
        return 0


def pretty_table(columns, rows):
    # Convert each cell to string
    str_rows = [[format_value_for_pretty(r.get(c) if isinstance(r, dict) else r[i]) for i, c in enumerate(columns)] for r in rows]
    widths = [visual_width(c) for c in columns]
    for r in str_rows:
        for i, cell in enumerate(r):
            w = visual_width(cell)
            if w > widths[i]:
                widths[i] = w
    # Right-align numeric, left-align text
    # Determine per-column alignment by data type: if all cells parse as numbers, right-align
    right_align = []
    for i, c in enumerate(columns):
        all_num = True
        any_val = False
        for r in str_rows:
            v = r[i]
            if v == 'null' or v == '':
                continue
            any_val = True
            try:
                float(v)
            except ValueError:
                all_num = False
                break
        right_align.append(all_num and any_val)
    out = []
    # Build separator
    sep = '+' + '+'.join(['-' * (w + 2) for w in widths]) + '+'
    # Header – centered
    hdr_cells = []
    for c, w in zip(columns, widths):
        s = str(c)
        pad = w - visual_width(s)
        left = pad // 2
        right = pad - left
        hdr_cells.append(' ' + (' ' * left) + s + (' ' * right) + ' ')
    out.append(sep)
    out.append('|' + '|'.join(hdr_cells) + '|')
    out.append(sep)
    for r in str_rows:
        cells = []
        for i, cell in enumerate(r):
            w = widths[i]
            s = str(cell)
            pad = w - visual_width(s)
            if right_align[i]:
                cells.append(' ' + (' ' * pad) + s + ' ')
            else:
                cells.append(' ' + s + (' ' * pad) + ' ')
        out.append('|' + '|'.join(cells) + '|')
    out.append(sep)
    out.append('(%d row%s)' % (len(rows), '' if len(rows) == 1 else 's'))
    return '\n'.join(out) + '\n'


def dump_pretty_from_records(records):
    """Pretty table directly from records, without SQL."""
    # Flatten only 1 level? Actually the observed behavior shows nested
    # objects/arrays stringified in cells.
    cols = []
    seen = set()
    for r in records:
        if not isinstance(r, dict):
            continue
        for k in r.keys():
            if k not in seen:
                seen.add(k)
                cols.append(k)
    rows = []
    for r in records:
        row = OrderedDict()
        for c in cols:
            v = r.get(c) if isinstance(r, dict) else None
            if isinstance(v, (dict, list)):
                row[c] = json.dumps(v, separators=(',', ':'))
            else:
                row[c] = v
        rows.append(row)
    return pretty_table(cols, rows)


# ---- Data loading ----

def load_file(path, fmt=None):
    """Load a file and return (records, fmt).

    records is a Python object suitable for passing to SQL.
    """
    if fmt is None:
        fmt = detect_format_by_ext(path)
        if fmt is None:
            raise ValueError("Unknown mimetype for file: %s." % path)
    if not os.path.exists(path):
        raise FileNotFoundError("open %s: no such file or directory" % path)
    if fmt == 'csv':
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
        rows, _ = read_csv_text(text, delim=',')
        return rows, fmt
    if fmt == 'tsv':
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
        rows, _ = read_csv_text(text, delim='\t')
        return rows, fmt
    if fmt == 'json':
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
        return read_json_text(text, path), fmt
    if fmt in ('ndjson', 'jsonl'):
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
        return read_ndjson_text(text), fmt
    if fmt == 'logfmt':
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
        return read_logfmt_text(text), fmt
    if fmt == 'xlsx':
        sheets = parse_xlsx_file(path)
        if len(sheets) == 1:
            return list(sheets.values())[0], fmt
        return sheets, fmt  # multi-sheet returns dict
    raise ValueError("Format %s not supported" % fmt)


def records_from_passthrough_file(path, fmt):
    """Return the raw bytes/text to dump when no query is given."""
    with open(path, 'rb') as f:
        return f.read()


# ---- Main ----

def parse_args(argv):
    opts = {
        'pretty': False,
        'schema': False,
        'cache': False,
        'interactive': False,
        'stdin_format': None,
        'query_file': None,
    }
    positional = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            print(HELP_TEXT, end='')
            sys.exit(2)
        elif a in ('-v', '--version'):
            print("dsq latest")
            sys.exit(0)
        elif a in ('-p', '--pretty'):
            opts['pretty'] = True
        elif a in ('--schema',):
            opts['schema'] = True
        elif a in ('-C', '--cache'):
            opts['cache'] = True
        elif a in ('-i', '--interactive'):
            opts['interactive'] = True
        elif a == '-s':
            i += 1
            if i >= len(argv):
                eprint("Missing value for -s")
                sys.exit(1)
            opts['stdin_format'] = argv[i]
        elif a.startswith('-s='):
            opts['stdin_format'] = a[3:]
        elif a in ('-f', '--file'):
            i += 1
            if i >= len(argv):
                eprint("Missing value for -f")
                sys.exit(1)
            opts['query_file'] = argv[i]
        elif a.startswith('--file='):
            opts['query_file'] = a[len('--file='):]
        else:
            positional.append(a)
        i += 1
    return opts, positional


def main(argv):
    opts, positional = parse_args(argv)

    query = None
    files = []

    if opts['stdin_format']:
        # Stdin mode: read from stdin. All positional args are query candidates.
        stdin_bytes = sys.stdin.buffer.read()
        # Write to a tempfile with expected extension
        ext_map = {
            'csv': '.csv', 'tsv': '.tsv', 'json': '.json', 'ndjson': '.ndjson',
            'jsonl': '.jsonl', 'xlsx': '.xlsx', 'parquet': '.parquet', 'ods': '.ods',
            'avro': '.avro', 'orc': '.orc', 'logfmt': '.logfmt'
        }
        fmt = opts['stdin_format']
        suffix = ext_map.get(fmt, '.' + fmt)
        tf = tempfile.NamedTemporaryFile(prefix='dsq-stdin', suffix=suffix, delete=False, mode='wb')
        try:
            tf.write(stdin_bytes)
            tf.close()
            files.append((tf.name, fmt))
            # All positional args = optional query
            if positional:
                query = ' '.join(positional)
            return run(opts, files, query, stdin_temp_path=tf.name)
        finally:
            try:
                os.unlink(tf.name)
            except OSError:
                pass

    # Non-stdin mode: figure out files vs query
    if not positional:
        eprint("No input files.")
        sys.exit(1)

    if opts['query_file']:
        # All positional are files, query comes from -f file
        with open(opts['query_file'], 'r') as f:
            query = f.read()
        for p in positional:
            fmt = detect_format_by_ext(p)
            files.append((p, fmt))
    else:
        # If only one positional, it's a file, no query.
        # If multiple positional, last is query.
        if len(positional) == 1:
            files.append((positional[0], detect_format_by_ext(positional[0])))
        else:
            for p in positional[:-1]:
                files.append((p, detect_format_by_ext(p)))
            query = positional[-1]

    return run(opts, files, query)


def run(opts, files, query, stdin_temp_path=None):
    # Validate all file formats are known
    for path, fmt in files:
        if fmt is None:
            eprint("Unknown mimetype for file: %s." % path)
            sys.exit(1)

    # Dump or schema mode (no query)
    if query is None:
        # First file is the one we operate on for dump/schema mode
        path, fmt = files[0]
        try:
            records, fmt2 = load_file(path, fmt)
        except FileNotFoundError as e:
            eprint(str(e))
            sys.exit(1)

        if opts['schema']:
            schema = infer_schema(records)
            if opts['pretty']:
                sys.stdout.write(format_schema_pretty(schema))
            else:
                sys.stdout.write(format_schema_json(schema) + '\n')
            return

        if opts['pretty']:
            if isinstance(records, list):
                sys.stdout.write(dump_pretty_from_records(records))
            else:
                # Scalar or object – wrap
                sys.stdout.write(dump_pretty_from_records([records] if isinstance(records, dict) else []))
            return

        # Plain dump: for json/logfmt files dsq passes through raw bytes;
        # for ndjson/jsonl and csv/tsv/xlsx it formats.
        if fmt in ('csv', 'tsv', 'logfmt'):
            # Format as JSON array
            sys.stdout.write(format_json_array(records if isinstance(records, list) else [records]))
            return
        if fmt in ('ndjson', 'jsonl'):
            sys.stdout.write(format_json_array(records))
            return
        if fmt == 'json':
            # Raw passthrough (with trailing extra newline behaviour)
            with open(path, 'rb') as f:
                data = f.read()
            sys.stdout.buffer.write(data)
            # Ensure output ends with exactly two newlines if original had at least one
            if not data.endswith(b'\n'):
                sys.stdout.buffer.write(b'\n')
            sys.stdout.buffer.write(b'\n')
            return
        if fmt == 'xlsx':
            if isinstance(records, dict):
                # Multi-sheet
                out = '{'
                parts = []
                for name, rows in records.items():
                    parts.append(json.dumps(name, ensure_ascii=False) + ': ' + format_json_array(rows).rstrip('\n'))
                out += ', '.join(parts) + '}\n'
                sys.stdout.write(out)
            else:
                sys.stdout.write(format_json_array(records))
            return
        # Default: format as JSON
        sys.stdout.write(format_json_array(records if isinstance(records, list) else [records]))
        return

    # Query mode
    all_records = []
    for path, fmt in files:
        try:
            records, _ = load_file(path, fmt)
        except FileNotFoundError as e:
            eprint(str(e))
            sys.exit(1)
        if not isinstance(records, list):
            eprint("Input is not an array of objects: %s." % path)
            sys.exit(1)
        # All items must be dicts
        if not all(isinstance(x, dict) for x in records):
            eprint("Input is not an array of objects: %s." % path)
            sys.exit(1)
        all_records.append(records)

    columns, rows = run_query(all_records, query)

    if opts['schema']:
        # Schema of result
        schema = infer_schema([dict(r) for r in rows])
        if opts['pretty']:
            sys.stdout.write(format_schema_pretty(schema))
        else:
            sys.stdout.write(format_schema_json(schema) + '\n')
        return

    if opts['pretty']:
        sys.stdout.write(pretty_table(columns, rows))
        return

    sys.stdout.write(format_json_array([dict(r) for r in rows]))


