    with zipfile.ZipFile(path, 'r') as z:
        # Read shared strings
        shared = []
        if 'xl/sharedStrings.xml' in z.namelist():
            with z.open('xl/sharedStrings.xml') as f:
                tree = ET.parse(f)
                root = tree.getroot()
                ns = {'a': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                for si in root.findall('a:si', ns):
                    # Accumulate text across all <t> children (handles rich text)
                    parts = []
                    for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'):
                        parts.append(t.text or '')
                    shared.append(''.join(parts))
        # Read styles to get per-xf number formats
        numfmts = dict(BUILTIN_XLSX_NUMFMTS)
        xf_fmts = []  # list of numFmtId per cellXfs entry
        if 'xl/styles.xml' in z.namelist():
            with z.open('xl/styles.xml') as f:
                tree = ET.parse(f)
                root = tree.getroot()
                ns_main = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
                for nf in root.iter('{%s}numFmt' % ns_main):
                    try:
                        fid = int(nf.get('numFmtId'))
                        code = nf.get('formatCode', '')
                        numfmts[fid] = code
                    except (ValueError, TypeError):
                        pass
                for cxfs in root.iter('{%s}cellXfs' % ns_main):
                    for xf in cxfs.findall('{%s}xf' % ns_main):
                        try:
                            fid = int(xf.get('numFmtId', '0'))
                        except ValueError:
                            fid = 0
                        xf_fmts.append(fid)'''
