def xlsx_serial_to_date_str(serial, fmt):
    import datetime
    try:
        s = float(serial)
    except (TypeError, ValueError):
        return str(serial)
    # Excel epoch: 1899-12-30 (Lotus bug)
    base = datetime.datetime(1899, 12, 30)
    try:
        dt = base + datetime.timedelta(days=s)
    except (ValueError, OverflowError):
        return str(serial)
    f = fmt.lower() if fmt else ''
    # Very small set of formats
    if 'yyyy' in f:
        y = '%Y'
    else:
        y = '%y'
    if 'm/d' in f or 'd/m' in f or 'd-m' in f:
        if 'yyyy' in f:
            return '%d/%d/%d' % (dt.month, dt.day, dt.year)
        return '%d/%d/%s' % (dt.month, dt.day, ('%02d' % (dt.year % 100)))
    if 'h:' in f or 'h:mm' in f:
        # date+time
        return dt.strftime('%Y-%m-%d %H:%M:%S')
    # Default ISO
    return dt.strftime('%Y-%m-%d')


def format_xlsx_number(text, fmt):
    """Format a numeric text using an xlsx format code (very partial)."""
    try:
        n = float(text)
    except (TypeError, ValueError):
        return text
    if fmt is None or fmt in ('General', ''):
        # Strip trailing .0 if integer
        if n == int(n):
            return str(int(n))
        return text
    f = fmt.lower()
    # Date-ish formats
    if any(k in f for k in ('y', 'd', 'mmm', 'mm/', 'm/d', 'd/m', 'd-m', 'h:', 'hh:', ':mm', ':ss')):
        if 'h' not in f and ':' not in f:
            # pure date
            return xlsx_serial_to_date_str(n, fmt)
        return xlsx_serial_to_date_str(n, fmt)
    # Integer-ish formats
    if fmt in ('0', '#,##0'):
        return str(int(round(n)))
    # Default: drop .0 for whole numbers
    if n == int(n):
        return str(int(n))
    return text


